    SUM(xn_f) ste_f,
    SUM(CASE WHEN in_w THEN x_r END) x_r,
    SUM(CASE WHEN in_w THEN t_r END) t_r,
    SUM(CASE WHEN in_w THEN w_r END) w_r,
    SUM(CASE WHEN in_w THEN c_r END) c_r,
    SUM(CASE WHEN in_w THEN xn_r END) mx_r,
    SUM(xn_r) ste_r,
    SUM(CASE WHEN in_w THEN x_d END) x_d,
    SUM(CASE WHEN in_w THEN t_d END) t_d,
    SUM(CASE WHEN in_w THEN w_d END) w_d,
    SUM(CASE WHEN in_w THEN c_d END) c_d,
    SUM(CASE WHEN in_w THEN xn_d END) mx_d,
    SUM(xn_d) ste_d,
    SUM(CASE WHEN in_w THEN x_c END) x_c,
    SUM(CASE WHEN in_w THEN t_c END) t_c,
    SUM(CASE WHEN in_w THEN w_c END) w_c,
    SUM(CASE WHEN in_w THEN c_c END) c_c,
    SUM(CASE WHEN in_w THEN xn_c END) mx_c,
    SUM(xn_c) ste_c,
    SUM(CASE WHEN in_w THEN x_dc END) x_dc,
    SUM(CASE WHEN in_w THEN t_dc END) t_dc,
    SUM(CASE WHEN in_w THEN w_dc END) w_dc,
    SUM(CASE WHEN in_w THEN c_dc END) c_dc,
    SUM(CASE WHEN in_w THEN xn_dc END) mx_dc,
    SUM(xn_dc) ste_dc,
    SUM(bx_all) bx_all, SUM(bx_crct) bx_crct, SUM(bx_usbd) bx_usbd, SUM(bx_dc) bx_dc
  FROM (SELECT *, exam_date BETWEEN DATE(start_date) AND DATE(end_date) AS in_w FROM edw_test.enterprise_analytics.mosaic_eff_managing_site_modes_mv)
  GROUP BY ALL
),
site AS (
  SELECT 'Full Mosaic' AS mode, pr, site, x_f x, t_f t, w_f w, c_f c, mx_f mx, ste_f ste, bx_all bx FROM site_sums
  UNION ALL
  SELECT 'Reporting Only', pr, site, x_r, t_r, w_r, c_r, mx_r, ste_r, bx_all FROM site_sums
  UNION ALL
  SELECT 'Drafting Only', pr, site, x_d, t_d, w_d, c_d, mx_d, ste_d, bx_crct FROM site_sums
  UNION ALL
  SELECT 'Capture Only', pr, site, x_c, t_c, w_c, c_c, mx_c, ste_c, bx_usbd FROM site_sums
  UNION ALL
  SELECT 'Drafting + Capture', pr, site, x_dc, t_dc, w_dc, c_dc, mx_dc, ste_dc, bx_dc FROM site_sums
),
surv AS (
  SELECT s.* FROM site s
  JOIN (SELECT mode, pr, SUM(x) px FROM site GROUP BY ALL) p ON p.mode = s.mode AND p.pr <=> s.pr
  WHERE s.x > 0 AND s.t > 0 AND s.c IS NOT NULL AND s.w IS NOT NULL AND p.px >= 1
    AND try_divide(s.c, s.t) <> 0 AND try_divide(s.w, s.t) <> 0
),
practice_rows AS (
  SELECT mode, 'Total' AS `Managing Practice`, 0 AS sort_key, COUNT(*) AS `Sites`,
    SUM(ste) ste, SUM(bx) bx, SUM(mx) mx, SUM(c) / SUM(t) b, 60 * SUM(w) / SUM(t) m
  FROM surv GROUP BY ALL
  UNION ALL
  SELECT mode, pr, 1, COUNT(*), SUM(ste), SUM(bx), SUM(mx), SUM(c) / SUM(t), 60 * SUM(w) / SUM(t)
  FROM surv GROUP BY ALL
),
site_rows AS (
  SELECT mode, pr AS `Managing Practice`, site AS `Site`, ste, bx, mx, c / t b, 60 * w / t m
  FROM surv
)
SELECT mode AS `Mode`, * EXCEPT (mode, ste, bx, mx, b, m),
  CASE WHEN ste > 0 THEN ste END AS `Site Total Mosaic Exams`,
  CASE WHEN bx > 0 THEN bx END AS `Baseline Exams`,
  CASE WHEN mx > 0 THEN mx END AS `Mosaic Exams`,
  b AS `Baseline Efficiency`, m AS `Mosaic Efficiency`,
  try_divide(m - b, b) AS `Pct Change Vs Baseline`,
  1 - try_divide(b, m) AS `Implied Read Time Savings Pct`,
  DATE(start_date) AS `Window Start`, DATE(end_date) AS `Window End`
FROM site_rows
;

CREATE OR REPLACE FUNCTION edw_test.enterprise_analytics.mosaic_eff_vs_avg_benchmarks(
  start_date STRING COMMENT 'First exam date of the window, YYYY-MM-DD (inclusive)',
  end_date STRING COMMENT 'Last exam date of the window, YYYY-MM-DD (inclusive)',
  min_exams INT DEFAULT 100 COMMENT 'PowerBI Min exams slicer; default 100'
)
RETURNS TABLE
COMMENT 'PowerBI ''Mosaic Efficiency vs Average'' benchmark cards per Mode: qualifying radiologists, Pop Avg Efficiency, RP Avg Efficiency Overall and the shown-population benchmark. Mode is one of: Full Mosaic, Reporting Only, Drafting Only, Capture Only, Drafting + Capture; filter on it. start_date / end_date are inclusive exam dates as ''YYYY-MM-DD'' strings (e.g. ''2026-09-01'', ''2026-09-30'' for September 2026); use complete months. min_exams = PowerBI ''Min exams'' slicer, default 100.'
RETURN
WITH prm AS (SELECT min_exams AS p_min),
lf AS (
  SELECT team_rolled_up AS team, radiologist AS rad, parent_exam AS proc,
    SUM(CASE WHEN in_w THEN x_d END) xd,
    SUM(CASE WHEN in_w THEN t_d END) td,
    SUM(CASE WHEN in_w THEN w_d END) wd,
    SUM(CASE WHEN in_w THEN x_c END) xc,
    SUM(CASE WHEN in_w THEN t_c END) tc,
    SUM(CASE WHEN in_w THEN w_c END) wc,
    SUM(CASE WHEN in_w THEN x_a END) xa,
    SUM(CASE WHEN in_w THEN t_a END) ta,
    SUM(CASE WHEN in_w THEN w_a END) wa,
    SUM(CASE WHEN in_w THEN x_r END) xr,
    SUM(CASE WHEN in_w THEN t_r END) tr,
    SUM(CASE WHEN in_w THEN w_r END) wr,
    SUM(x_d) all_d, SUM(x_c) all_c, SUM(x_a) all_a, SUM(x_r) all_r,
    MAX(CASE WHEN in_w THEN 1 END) in_window
  FROM (SELECT *, exam_date BETWEEN DATE(start_date) AND DATE(end_date) AS in_w FROM edw_test.enterprise_analytics.mosaic_eff_vs_avg_daily_mv)
  GROUP BY ALL
),
lw AS (
  SELECT *,
    CASE WHEN xd IS NOT NULL OR xc IS NOT NULL THEN COALESCE(xd, 0) + COALESCE(xc, 0) END xdc,
    CASE WHEN td IS NOT NULL OR tc IS NOT NULL THEN COALESCE(td, 0) + COALESCE(tc, 0) END tdc,
    CASE WHEN wd IS NOT NULL OR wc IS NOT NULL THEN COALESCE(wd, 0) + COALESCE(wc, 0) END wdc,
    CASE WHEN xa IS NOT NULL OR xr IS NOT NULL THEN COALESCE(xa, 0) + COALESCE(xr, 0) END xf,
    CASE WHEN ta IS NOT NULL OR tr IS NOT NULL THEN COALESCE(ta, 0) + COALESCE(tr, 0) END tf,
    CASE WHEN wa IS NOT NULL OR wr IS NOT NULL THEN COALESCE(wa, 0) + COALESCE(wr, 0) END wf,
    CASE WHEN all_d IS NOT NULL OR all_c IS NOT NULL THEN COALESCE(all_d, 0) + COALESCE(all_c, 0) END all_dc,
    CASE WHEN all_a IS NOT NULL OR all_r IS NOT NULL THEN COALESCE(all_a, 0) + COALESCE(all_r, 0) END all_f
  FROM lf WHERE in_window = 1
),
leaf AS (
  SELECT 'Drafting Only' AS mode, team, rad, proc, xd q, xd p, ta et, wa ew, all_d ax, xd bx, td bt, wd bw FROM lw
  UNION ALL
  SELECT 'Reporting Only', team, rad, proc, xr, xr, tr, wr, all_r, xr, tr, wr FROM lw
  UNION ALL
  SELECT 'Capture Only', team, rad, proc, xc, xf, tc, wc, all_f, xc, tc, wc FROM lw
  UNION ALL
  SELECT 'Drafting + Capture', team, rad, proc, xdc, xdc, tf, wf, all_dc, xdc, tdc, wdc FROM lw
  UNION ALL
  SELECT 'Full Mosaic', team, rad, proc, xf, xf, tf, wf, all_f, xf, tf, wf FROM lw
),
rad_q AS (
  SELECT mode, team, rad, COALESCE(SUM(q), 0) >= MAX(p_min) AS qualifies FROM leaf CROSS JOIN prm GROUP BY mode, team, rad
),
vf AS (
  SELECT l.* FROM leaf l JOIN rad_q r ON r.mode = l.mode AND r.team <=> l.team AND r.rad <=> l.rad
  WHERE r.qualifies AND l.p > 0 AND l.et > 0 AND l.ew IS NOT NULL
),
card_rad AS (
  SELECT mode, rad, SUM(bx) bx, SUM(bt) bt, SUM(bw) bw, SUM(q) q, SUM(p) p, SUM(et) et, SUM(ew) ew
  FROM leaf GROUP BY ALL
),
cards AS (
  SELECT mode,
    COUNT(CASE WHEN COALESCE(q, 0) >= p_min AND p > 0 AND et > 0 AND ew IS NOT NULL THEN 1 END) AS radiologists,
    SUM(CASE WHEN COALESCE(bx, 0) >= p_min AND bt > 0 THEN bw END)
      / (SUM(CASE WHEN COALESCE(bx, 0) >= p_min AND bt > 0 THEN bt END) / 60) AS pop_avg,
    SUM(CASE WHEN COALESCE(bx, 0) >= p_min THEN bw END)
      / (SUM(CASE WHEN COALESCE(bx, 0) >= p_min THEN bt END) / 60) AS overall_avg
  FROM card_rad CROSS JOIN prm GROUP BY mode
),
tp AS (SELECT DISTINCT mode, team, proc FROM vf),
shown_rad AS (
  SELECT l.mode, l.rad, SUM(l.bx) bx, SUM(l.bt) bt, SUM(l.bw) bw
  FROM leaf l
  JOIN (SELECT DISTINCT mode, rad FROM vf) r ON r.mode = l.mode AND r.rad <=> l.rad
  JOIN tp ON tp.mode = l.mode AND tp.team <=> l.team AND tp.proc <=> l.proc
  GROUP BY ALL
),
bench AS (
  SELECT c.mode, c.radiologists, c.pop_avg, c.overall_avg,
    s.bw / (s.bt / 60) AS shown_avg
  FROM cards c LEFT JOIN (
    SELECT mode, SUM(CASE WHEN COALESCE(bx, 0) >= p_min AND bt > 0 THEN bw END) bw,
      SUM(CASE WHEN COALESCE(bx, 0) >= p_min AND bt > 0 THEN bt END) bt
    FROM shown_rad CROSS JOIN prm GROUP BY mode
  ) s ON s.mode = c.mode
),
dim AS (
  SELECT team_rolled_up AS team, radiologist AS rad, MAX(subspecialty) AS subspecialty,
    SUM(rad_total_drafting) tot_d, SUM(rad_total_reporting) tot_r, SUM(rad_total_fullmosaic) tot_f
  FROM edw_test.enterprise_analytics.mosaic_eff_vs_avg_rad_dim_mv GROUP BY ALL
),
vf_rad AS (
  SELECT v.mode, v.team, v.rad, SUM(v.p) p, SUM(v.et) et, SUM(v.ew) ew,
    CASE v.mode WHEN 'Drafting Only' THEN MAX(dm.tot_d) WHEN 'Reporting Only' THEN MAX(dm.tot_r)
      WHEN 'Drafting + Capture' THEN SUM(v.ax) ELSE MAX(dm.tot_f) END AS alltime,
    MAX(dm.subspecialty) AS subspecialty
  FROM vf v LEFT JOIN dim dm ON dm.team <=> v.team AND dm.rad <=> v.rad
  GROUP BY ALL
),
card_rows AS (
  SELECT mode, CASE mode WHEN 'Drafting Only' THEN 1 WHEN 'Capture Only' THEN 2 WHEN 'Drafting + Capture' THEN 3
      WHEN 'Reporting Only' THEN 4 ELSE 5 END AS sort_key, radiologists AS `Radiologists`, pop_avg AS `Pop Avg Efficiency`,
    overall_avg AS `RP Avg Efficiency Overall`, shown_avg AS `Shown Population Benchmark`
  FROM bench
),
team_rows AS (
  SELECT r.mode, r.team AS `Provider Practice`, 1 AS sort_key, COUNT(*) AS `Radiologists`,
    SUM(r.alltime) AS `Mosaic Exams All Time`, SUM(r.p) AS `Mosaic Exams Period`,
    SUM(r.ew) / (SUM(r.et) / 60) AS `Mosaic Efficiency`,
    SUM(r.ew) / (SUM(r.et) / 60) / MAX(b.overall_avg) AS `Vs RP Avg Overall`,
    SUM(r.ew) / (SUM(r.et) / 60) / MAX(b.shown_avg) AS `Vs RP Avg`
  FROM vf_rad r JOIN bench b ON b.mode = r.mode GROUP BY ALL
  UNION ALL
  SELECT r.mode, 'Total', 0, COUNT(DISTINCT r.rad), SUM(r.alltime), SUM(r.p),
    MAX(b.shown_avg), MAX(b.shown_avg) / MAX(b.overall_avg), 1.0
  FROM vf_rad r JOIN bench b ON b.mode = r.mode GROUP BY ALL
),
radiologist_rows AS (
  SELECT r.mode, r.team AS `Provider Practice`, r.rad AS `Radiologist`, r.subspecialty AS `Subspecialty`,
    r.alltime AS `Mosaic Exams All Time`, r.p AS `Mosaic Exams Period`, r.ew / (r.et / 60) AS `Mosaic Efficiency`,
    r.ew / (r.et / 60) / b.overall_avg AS `Vs RP Avg Overall`, r.ew / (r.et / 60) / b.shown_avg AS `Vs RP Avg`
  FROM vf_rad r JOIN bench b ON b.mode = r.mode
),
parent_exam_rows AS (
  SELECT v.mode, v.team AS `Provider Practice`, v.rad AS `Radiologist`, v.proc AS `Parent Exam`,
    dm.subspecialty AS `Subspecialty`, v.ax AS `Mosaic Exams All Time`, v.p AS `Mosaic Exams Period`,
    v.ew / (v.et / 60) AS `Mosaic Efficiency`, v.ew / (v.et / 60) / b.overall_avg AS `Vs RP Avg Overall`,
    v.ew / (v.et / 60) / b.shown_avg AS `Vs RP Avg`
  FROM vf v JOIN bench b ON b.mode = v.mode LEFT JOIN dim dm ON dm.team <=> v.team AND dm.rad <=> v.rad
)
SELECT mode AS `Mode`, * EXCEPT (mode), DATE(start_date) AS `Window Start`, DATE(end_date) AS `Window End`
FROM card_rows
;

CREATE OR REPLACE FUNCTION edw_test.enterprise_analytics.mosaic_eff_vs_avg_by_practice(
  start_date STRING COMMENT 'First exam date of the window, YYYY-MM-DD (inclusive)',
  end_date STRING COMMENT 'Last exam date of the window, YYYY-MM-DD (inclusive)',
  min_exams INT DEFAULT 100 COMMENT 'PowerBI Min exams slicer; default 100'
)
RETURNS TABLE
COMMENT 'PowerBI ''Mosaic Efficiency vs Average'' by Provider Practice: Mosaic Efficiency and Vs RP Avg (ratio, 1.05 = 5% above the radiologist-population average), plus a ''Total'' row. Mode is one of: Full Mosaic, Reporting Only, Drafting Only, Capture Only, Drafting + Capture; filter on it. start_date / end_date are inclusive exam dates as ''YYYY-MM-DD'' strings (e.g. ''2026-09-01'', ''2026-09-30'' for September 2026); use complete months. min_exams default 100.'
RETURN
WITH prm AS (SELECT min_exams AS p_min),
lf AS (
  SELECT team_rolled_up AS team, radiologist AS rad, parent_exam AS proc,
    SUM(CASE WHEN in_w THEN x_d END) xd,
    SUM(CASE WHEN in_w THEN t_d END) td,
    SUM(CASE WHEN in_w THEN w_d END) wd,
    SUM(CASE WHEN in_w THEN x_c END) xc,
    SUM(CASE WHEN in_w THEN t_c END) tc,
    SUM(CASE WHEN in_w THEN w_c END) wc,
    SUM(CASE WHEN in_w THEN x_a END) xa,
    SUM(CASE WHEN in_w THEN t_a END) ta,
    SUM(CASE WHEN in_w THEN w_a END) wa,
    SUM(CASE WHEN in_w THEN x_r END) xr,
    SUM(CASE WHEN in_w THEN t_r END) tr,
    SUM(CASE WHEN in_w THEN w_r END) wr,
    SUM(x_d) all_d, SUM(x_c) all_c, SUM(x_a) all_a, SUM(x_r) all_r,
    MAX(CASE WHEN in_w THEN 1 END) in_window
  FROM (SELECT *, exam_date BETWEEN DATE(start_date) AND DATE(end_date) AS in_w FROM edw_test.enterprise_analytics.mosaic_eff_vs_avg_daily_mv)
  GROUP BY ALL
),
lw AS (
  SELECT *,
    CASE WHEN xd IS NOT NULL OR xc IS NOT NULL THEN COALESCE(xd, 0) + COALESCE(xc, 0) END xdc,
    CASE WHEN td IS NOT NULL OR tc IS NOT NULL THEN COALESCE(td, 0) + COALESCE(tc, 0) END tdc,
    CASE WHEN wd IS NOT NULL OR wc IS NOT NULL THEN COALESCE(wd, 0) + COALESCE(wc, 0) END wdc,
    CASE WHEN xa IS NOT NULL OR xr IS NOT NULL THEN COALESCE(xa, 0) + COALESCE(xr, 0) END xf,
    CASE WHEN ta IS NOT NULL OR tr IS NOT NULL THEN COALESCE(ta, 0) + COALESCE(tr, 0) END tf,
    CASE WHEN wa IS NOT NULL OR wr IS NOT NULL THEN COALESCE(wa, 0) + COALESCE(wr, 0) END wf,
    CASE WHEN all_d IS NOT NULL OR all_c IS NOT NULL THEN COALESCE(all_d, 0) + COALESCE(all_c, 0) END all_dc,
    CASE WHEN all_a IS NOT NULL OR all_r IS NOT NULL THEN COALESCE(all_a, 0) + COALESCE(all_r, 0) END all_f
  FROM lf WHERE in_window = 1
),
leaf AS (
  SELECT 'Drafting Only' AS mode, team, rad, proc, xd q, xd p, ta et, wa ew, all_d ax, xd bx, td bt, wd bw FROM lw
  UNION ALL
  SELECT 'Reporting Only', team, rad, proc, xr, xr, tr, wr, all_r, xr, tr, wr FROM lw
  UNION ALL
  SELECT 'Capture Only', team, rad, proc, xc, xf, tc, wc, all_f, xc, tc, wc FROM lw
  UNION ALL
  SELECT 'Drafting + Capture', team, rad, proc, xdc, xdc, tf, wf, all_dc, xdc, tdc, wdc FROM lw
  UNION ALL
  SELECT 'Full Mosaic', team, rad, proc, xf, xf, tf, wf, all_f, xf, tf, wf FROM lw
),
rad_q AS (
  SELECT mode, team, rad, COALESCE(SUM(q), 0) >= MAX(p_min) AS qualifies FROM leaf CROSS JOIN prm GROUP BY mode, team, rad
),
vf AS (
  SELECT l.* FROM leaf l JOIN rad_q r ON r.mode = l.mode AND r.team <=> l.team AND r.rad <=> l.rad
  WHERE r.qualifies AND l.p > 0 AND l.et > 0 AND l.ew IS NOT NULL
),
card_rad AS (
  SELECT mode, rad, SUM(bx) bx, SUM(bt) bt, SUM(bw) bw, SUM(q) q, SUM(p) p, SUM(et) et, SUM(ew) ew
  FROM leaf GROUP BY ALL
),
cards AS (
  SELECT mode,
    COUNT(CASE WHEN COALESCE(q, 0) >= p_min AND p > 0 AND et > 0 AND ew IS NOT NULL THEN 1 END) AS radiologists,
    SUM(CASE WHEN COALESCE(bx, 0) >= p_min AND bt > 0 THEN bw END)
      / (SUM(CASE WHEN COALESCE(bx, 0) >= p_min AND bt > 0 THEN bt END) / 60) AS pop_avg,
    SUM(CASE WHEN COALESCE(bx, 0) >= p_min THEN bw END)
      / (SUM(CASE WHEN COALESCE(bx, 0) >= p_min THEN bt END) / 60) AS overall_avg
  FROM card_rad CROSS JOIN prm GROUP BY mode
),
tp AS (SELECT DISTINCT mode, team, proc FROM vf),
shown_rad AS (
  SELECT l.mode, l.rad, SUM(l.bx) bx, SUM(l.bt) bt, SUM(l.bw) bw
  FROM leaf l
  JOIN (SELECT DISTINCT mode, rad FROM vf) r ON r.mode = l.mode AND r.rad <=> l.rad
  JOIN tp ON tp.mode = l.mode AND tp.team <=> l.team AND tp.proc <=> l.proc
  GROUP BY ALL
),
bench AS (
  SELECT c.mode, c.radiologists, c.pop_avg, c.overall_avg,
    s.bw / (s.bt / 60) AS shown_avg
  FROM cards c LEFT JOIN (
    SELECT mode, SUM(CASE WHEN COALESCE(bx, 0) >= p_min AND bt > 0 THEN bw END) bw,
      SUM(CASE WHEN COALESCE(bx, 0) >= p_min AND bt > 0 THEN bt END) bt
    FROM shown_rad CROSS JOIN prm GROUP BY mode
  ) s ON s.mode = c.mode
),
dim AS (
  SELECT team_rolled_up AS team, radiologist AS rad, MAX(subspecialty) AS subspecialty,
    SUM(rad_total_drafting) tot_d, SUM(rad_total_reporting) tot_r, SUM(rad_total_fullmosaic) tot_f
  FROM edw_test.enterprise_analytics.mosaic_eff_vs_avg_rad_dim_mv GROUP BY ALL
),
vf_rad AS (
  SELECT v.mode, v.team, v.rad, SUM(v.p) p, SUM(v.et) et, SUM(v.ew) ew,
    CASE v.mode WHEN 'Drafting Only' THEN MAX(dm.tot_d) WHEN 'Reporting Only' THEN MAX(dm.tot_r)
      WHEN 'Drafting + Capture' THEN SUM(v.ax) ELSE MAX(dm.tot_f) END AS alltime,
    MAX(dm.subspecialty) AS subspecialty
  FROM vf v LEFT JOIN dim dm ON dm.team <=> v.team AND dm.rad <=> v.rad
  GROUP BY ALL
),
card_rows AS (
  SELECT mode, CASE mode WHEN 'Drafting Only' THEN 1 WHEN 'Capture Only' THEN 2 WHEN 'Drafting + Capture' THEN 3
      WHEN 'Reporting Only' THEN 4 ELSE 5 END AS sort_key, radiologists AS `Radiologists`, pop_avg AS `Pop Avg Efficiency`,
    overall_avg AS `RP Avg Efficiency Overall`, shown_avg AS `Shown Population Benchmark`
  FROM bench
),
team_rows AS (
  SELECT r.mode, r.team AS `Provider Practice`, 1 AS sort_key, COUNT(*) AS `Radiologists`,
    SUM(r.alltime) AS `Mosaic Exams All Time`, SUM(r.p) AS `Mosaic Exams Period`,
    SUM(r.ew) / (SUM(r.et) / 60) AS `Mosaic Efficiency`,
    SUM(r.ew) / (SUM(r.et) / 60) / MAX(b.overall_avg) AS `Vs RP Avg Overall`,
    SUM(r.ew) / (SUM(r.et) / 60) / MAX(b.shown_avg) AS `Vs RP Avg`
  FROM vf_rad r JOIN bench b ON b.mode = r.mode GROUP BY ALL
  UNION ALL
  SELECT r.mode, 'Total', 0, COUNT(DISTINCT r.rad), SUM(r.alltime), SUM(r.p),
    MAX(b.shown_avg), MAX(b.shown_avg) / MAX(b.overall_avg), 1.0
  FROM vf_rad r JOIN bench b ON b.mode = r.mode GROUP BY ALL
),
radiologist_rows AS (
  SELECT r.mode, r.team AS `Provider Practice`, r.rad AS `Radiologist`, r.subspecialty AS `Subspecialty`,
    r.alltime AS `Mosaic Exams All Time`, r.p AS `Mosaic Exams Period`, r.ew / (r.et / 60) AS `Mosaic Efficiency`,
    r.ew / (r.et / 60) / b.overall_avg AS `Vs RP Avg Overall`, r.ew / (r.et / 60) / b.shown_avg AS `Vs RP Avg`
  FROM vf_rad r JOIN bench b ON b.mode = r.mode
),
parent_exam_rows AS (
  SELECT v.mode, v.team AS `Provider Practice`, v.rad AS `Radiologist`, v.proc AS `Parent Exam`,
    dm.subspecialty AS `Subspecialty`, v.ax AS `Mosaic Exams All Time`, v.p AS `Mosaic Exams Period`,
    v.ew / (v.et / 60) AS `Mosaic Efficiency`, v.ew / (v.et / 60) / b.overall_avg AS `Vs RP Avg Overall`,
    v.ew / (v.et / 60) / b.shown_avg AS `Vs RP Avg`
  FROM vf v JOIN bench b ON b.mode = v.mode LEFT JOIN dim dm ON dm.team <=> v.team AND dm.rad <=> v.rad
)
SELECT mode AS `Mode`, * EXCEPT (mode), DATE(start_date) AS `Window Start`, DATE(end_date) AS `Window End`
FROM team_rows
;

CREATE OR REPLACE FUNCTION edw_test.enterprise_analytics.mosaic_eff_vs_avg_by_radiologist(
  start_date STRING COMMENT 'First exam date of the window, YYYY-MM-DD (inclusive)',
  end_date STRING COMMENT 'Last exam date of the window, YYYY-MM-DD (inclusive)',
  min_exams INT DEFAULT 100 COMMENT 'PowerBI Min exams slicer; default 100'
)
RETURNS TABLE
COMMENT 'PowerBI ''Mosaic Efficiency vs Average'' by radiologist: Mosaic Efficiency, Vs RP Avg and Vs RP Avg Overall (ratios to the average). Use for ''which radiologists are above / below average''. Mode is one of: Full Mosaic, Reporting Only, Drafting Only, Capture Only, Drafting + Capture; filter on it. start_date / end_date are inclusive exam dates as ''YYYY-MM-DD'' strings (e.g. ''2026-09-01'', ''2026-09-30'' for September 2026); use complete months. min_exams default 100.'
RETURN
WITH prm AS (SELECT min_exams AS p_min),
lf AS (
  SELECT team_rolled_up AS team, radiologist AS rad, parent_exam AS proc,
    SUM(CASE WHEN in_w THEN x_d END) xd,
    SUM(CASE WHEN in_w THEN t_d END) td,
    SUM(CASE WHEN in_w THEN w_d END) wd,
    SUM(CASE WHEN in_w THEN x_c END) xc,
    SUM(CASE WHEN in_w THEN t_c END) tc,
    SUM(CASE WHEN in_w THEN w_c END) wc,
    SUM(CASE WHEN in_w THEN x_a END) xa,
    SUM(CASE WHEN in_w THEN t_a END) ta,
    SUM(CASE WHEN in_w THEN w_a END) wa,
    SUM(CASE WHEN in_w THEN x_r END) xr,
    SUM(CASE WHEN in_w THEN t_r END) tr,
    SUM(CASE WHEN in_w THEN w_r END) wr,
    SUM(x_d) all_d, SUM(x_c) all_c, SUM(x_a) all_a, SUM(x_r) all_r,
    MAX(CASE WHEN in_w THEN 1 END) in_window
  FROM (SELECT *, exam_date BETWEEN DATE(start_date) AND DATE(end_date) AS in_w FROM edw_test.enterprise_analytics.mosaic_eff_vs_avg_daily_mv)
  GROUP BY ALL
),
lw AS (
  SELECT *,
    CASE WHEN xd IS NOT NULL OR xc IS NOT NULL THEN COALESCE(xd, 0) + COALESCE(xc, 0) END xdc,
    CASE WHEN td IS NOT NULL OR tc IS NOT NULL THEN COALESCE(td, 0) + COALESCE(tc, 0) END tdc,
    CASE WHEN wd IS NOT NULL OR wc IS NOT NULL THEN COALESCE(wd, 0) + COALESCE(wc, 0) END wdc,
    CASE WHEN xa IS NOT NULL OR xr IS NOT NULL THEN COALESCE(xa, 0) + COALESCE(xr, 0) END xf,
    CASE WHEN ta IS NOT NULL OR tr IS NOT NULL THEN COALESCE(ta, 0) + COALESCE(tr, 0) END tf,
    CASE WHEN wa IS NOT NULL OR wr IS NOT NULL THEN COALESCE(wa, 0) + COALESCE(wr, 0) END wf,
    CASE WHEN all_d IS NOT NULL OR all_c IS NOT NULL THEN COALESCE(all_d, 0) + COALESCE(all_c, 0) END all_dc,
    CASE WHEN all_a IS NOT NULL OR all_r IS NOT NULL THEN COALESCE(all_a, 0) + COALESCE(all_r, 0) END all_f
  FROM lf WHERE in_window = 1
),
leaf AS (
  SELECT 'Drafting Only' AS mode, team, rad, proc, xd q, xd p, ta et, wa ew, all_d ax, xd bx, td bt, wd bw FROM lw
  UNION ALL
  SELECT 'Reporting Only', team, rad, proc, xr, xr, tr, wr, all_r, xr, tr, wr FROM lw
  UNION ALL
  SELECT 'Capture Only', team, rad, proc, xc, xf, tc, wc, all_f, xc, tc, wc FROM lw
  UNION ALL
  SELECT 'Drafting + Capture', team, rad, proc, xdc, xdc, tf, wf, all_dc, xdc, tdc, wdc FROM lw
  UNION ALL
  SELECT 'Full Mosaic', team, rad, proc, xf, xf, tf, wf, all_f, xf, tf, wf FROM lw
),
rad_q AS (
  SELECT mode, team, rad, COALESCE(SUM(q), 0) >= MAX(p_min) AS qualifies FROM leaf CROSS JOIN prm GROUP BY mode, team, rad
),
vf AS (
  SELECT l.* FROM leaf l JOIN rad_q r ON r.mode = l.mode AND r.team <=> l.team AND r.rad <=> l.rad
  WHERE r.qualifies AND l.p > 0 AND l.et > 0 AND l.ew IS NOT NULL
),
card_rad AS (
  SELECT mode, rad, SUM(bx) bx, SUM(bt) bt, SUM(bw) bw, SUM(q) q, SUM(p) p, SUM(et) et, SUM(ew) ew
  FROM leaf GROUP BY ALL
),
cards AS (
  SELECT mode,
    COUNT(CASE WHEN COALESCE(q, 0) >= p_min AND p > 0 AND et > 0 AND ew IS NOT NULL THEN 1 END) AS radiologists,
    SUM(CASE WHEN COALESCE(bx, 0) >= p_min AND bt > 0 THEN bw END)
      / (SUM(CASE WHEN COALESCE(bx, 0) >= p_min AND bt > 0 THEN bt END) / 60) AS pop_avg,
    SUM(CASE WHEN COALESCE(bx, 0) >= p_min THEN bw END)
      / (SUM(CASE WHEN COALESCE(bx, 0) >= p_min THEN bt END) / 60) AS overall_avg
  FROM card_rad CROSS JOIN prm GROUP BY mode
),
tp AS (SELECT DISTINCT mode, team, proc FROM vf),
shown_rad AS (
  SELECT l.mode, l.rad, SUM(l.bx) bx, SUM(l.bt) bt, SUM(l.bw) bw
  FROM leaf l
  JOIN (SELECT DISTINCT mode, rad FROM vf) r ON r.mode = l.mode AND r.rad <=> l.rad
  JOIN tp ON tp.mode = l.mode AND tp.team <=> l.team AND tp.proc <=> l.proc
  GROUP BY ALL
),
bench AS (
  SELECT c.mode, c.radiologists, c.pop_avg, c.overall_avg,
    s.bw / (s.bt / 60) AS shown_avg
  FROM cards c LEFT JOIN (
    SELECT mode, SUM(CASE WHEN COALESCE(bx, 0) >= p_min AND bt > 0 THEN bw END) bw,
      SUM(CASE WHEN COALESCE(bx, 0) >= p_min AND bt > 0 THEN bt END) bt
    FROM shown_rad CROSS JOIN prm GROUP BY mode
  ) s ON s.mode = c.mode
),
dim AS (
  SELECT team_rolled_up AS team, radiologist AS rad, MAX(subspecialty) AS subspecialty,
    SUM(rad_total_drafting) tot_d, SUM(rad_total_reporting) tot_r, SUM(rad_total_fullmosaic) tot_f
  FROM edw_test.enterprise_analytics.mosaic_eff_vs_avg_rad_dim_mv GROUP BY ALL
),
vf_rad AS (
  SELECT v.mode, v.team, v.rad, SUM(v.p) p, SUM(v.et) et, SUM(v.ew) ew,
    CASE v.mode WHEN 'Drafting Only' THEN MAX(dm.tot_d) WHEN 'Reporting Only' THEN MAX(dm.tot_r)
      WHEN 'Drafting + Capture' THEN SUM(v.ax) ELSE MAX(dm.tot_f) END AS alltime,
    MAX(dm.subspecialty) AS subspecialty
  FROM vf v LEFT JOIN dim dm ON dm.team <=> v.team AND dm.rad <=> v.rad
  GROUP BY ALL
),
card_rows AS (
  SELECT mode, CASE mode WHEN 'Drafting Only' THEN 1 WHEN 'Capture Only' THEN 2 WHEN 'Drafting + Capture' THEN 3
      WHEN 'Reporting Only' THEN 4 ELSE 5 END AS sort_key, radiologists AS `Radiologists`, pop_avg AS `Pop Avg Efficiency`,
    overall_avg AS `RP Avg Efficiency Overall`, shown_avg AS `Shown Population Benchmark`
  FROM bench
),
team_rows AS (
  SELECT r.mode, r.team AS `Provider Practice`, 1 AS sort_key, COUNT(*) AS `Radiologists`,
    SUM(r.alltime) AS `Mosaic Exams All Time`, SUM(r.p) AS `Mosaic Exams Period`,
    SUM(r.ew) / (SUM(r.et) / 60) AS `Mosaic Efficiency`,
    SUM(r.ew) / (SUM(r.et) / 60) / MAX(b.overall_avg) AS `Vs RP Avg Overall`,
    SUM(r.ew) / (SUM(r.et) / 60) / MAX(b.shown_avg) AS `Vs RP Avg`
  FROM vf_rad r JOIN bench b ON b.mode = r.mode GROUP BY ALL
  UNION ALL
  SELECT r.mode, 'Total', 0, COUNT(DISTINCT r.rad), SUM(r.alltime), SUM(r.p),
    MAX(b.shown_avg), MAX(b.shown_avg) / MAX(b.overall_avg), 1.0
  FROM vf_rad r JOIN bench b ON b.mode = r.mode GROUP BY ALL
),
radiologist_rows AS (
  SELECT r.mode, r.team AS `Provider Practice`, r.rad AS `Radiologist`, r.subspecialty AS `Subspecialty`,
    r.alltime AS `Mosaic Exams All Time`, r.p AS `Mosaic Exams Period`, r.ew / (r.et / 60) AS `Mosaic Efficiency`,
    r.ew / (r.et / 60) / b.overall_avg AS `Vs RP Avg Overall`, r.ew / (r.et / 60) / b.shown_avg AS `Vs RP Avg`
  FROM vf_rad r JOIN bench b ON b.mode = r.mode
),
parent_exam_rows AS (
  SELECT v.mode, v.team AS `Provider Practice`, v.rad AS `Radiologist`, v.proc AS `Parent Exam`,
    dm.subspecialty AS `Subspecialty`, v.ax AS `Mosaic Exams All Time`, v.p AS `Mosaic Exams Period`,
    v.ew / (v.et / 60) AS `Mosaic Efficiency`, v.ew / (v.et / 60) / b.overall_avg AS `Vs RP Avg Overall`,
    v.ew / (v.et / 60) / b.shown_avg AS `Vs RP Avg`
  FROM vf v JOIN bench b ON b.mode = v.mode LEFT JOIN dim dm ON dm.team <=> v.team AND dm.rad <=> v.rad
)
SELECT mode AS `Mode`, * EXCEPT (mode), DATE(start_date) AS `Window Start`, DATE(end_date) AS `Window End`
FROM radiologist_rows
;
